props.default:
(query: string, children: ReactNode) => {
  return React.Children.toArray(children).filter((child) => {
    const title = (child as any).props.title;

    if (!title) {
      return false;
    }

    return title.toLowerCase().includes(query.toLowerCase());
  });
}

