import usePosition from "@talkdesk/cobalt-react-position-hook";

const Positioning = props => {

  // Node should be the node of the "anchor" element to be considered for positioning the other element
  // Origin and Direction must be one of: "N", "NE", "E", "SE", "S", "SW", "W", "NW"
  // autoGap/gapX/gapY is the margin (in px) between the "anchor" element and the positioned element.
  // The autoGap takes the origin and direction given and calculates where should the gap be applied
  // while gapX only sets it in the horizontal direction and gapY in the vertical direction.
  // The elementRef must be passed to the positioned element so that optimal positioning algorithm is applied

  const [node, setNode] = React.useState(null);
  const sourceRef = React.useCallback((n) => setNode(n), []);

  const { position, elementRef } = usePosition(node, {
    origin: "SE",
    direction: "E",
    autoGap: 0
  });

  return (
    <>
      <AnchorElement forwardedRef={sourceRef} />

      <PositionedElement forwardedRef={elementRef} style={{ ...position }}>
        ...
      </PositionedElement>
    </>
  );
};

import useResize from "@talkdesk/cobalt-react-resize-hook";

const Component = () => {

// To be able to resize ElementB based on ElementA dimensions, it is necessary
// to use useResize hook, passing the ElementA ref as argument.
// The hook returns an object with width and height properties, which can then be
// applied to ElementB styling, so it is resized based on ElementA width and height
// and reacts to ElementA dimensions being changed.

const [ref, setRef] = useState(null);

const fnRef = useCallback((el) => {
  setRef(el);
}, []);

const resizeStyle = useResize(ref);

return (
  <>
    <ElementA ref={fnRef}/>

    <ElementB style={{ width: 10, height: 20,...resizeStyle }} />
  </>
)

import useResize from "@talkdesk/cobalt-react-resize-hook";

const Component = () => {

// To be able to resize ElementB based on ElementA width, it is necessary
// to use useResize hook, passing the ElementA ref as argument.
// The hook returns an object with width and height properties, which can then be
// deestructured to use only width, to apply to ElementB styling, so it is resized
// based on ElementA width.
// The same applies if we want to resize ElementB height according to ElementA height.

const [ref, setRef] = useState(null);

const fnRef = useCallback((el) => {
  setRef(el);
}, []);

const { width } = useResize(ref);

return (
  <>
    <ElementA ref={fnRef}/>

    <ElementB style={{ width }} />
  </>
)

