const RootComponent = () => {
  const [target, setTarget] = useState();
  const wrapper = useRef();

  useLayoutEffect(() => {
    if (wrapper.current !== null) setTarget(wrapper.current);
  }, []);

  return (
    <div ref={wrapper} style={{ border: "5px solid red" }}>
      {target && (
        <ViewportProvider target={target}>
          <Component />
        </ViewportProvider>
      )}
    </div>
  );
};
